package main

import "fmt"

type Inventory struct {
	Items  [100]string
	Counts [100]int
	Size   int
}

func addItemByValue(inv Inventory, item string, count int) Inventory {
	// Must return modified copy
	if inv.Size < 100 {
		inv.Items[inv.Size] = item
		inv.Counts[inv.Size] = count
		inv.Size++
	}
	return inv
}

func addItemByPointer(inv *Inventory, item string, count int) {
	// Modifies directly
	if inv.Size < 100 {
		inv.Items[inv.Size] = item
		inv.Counts[inv.Size] = count
		inv.Size++
	}
}

type Player struct {
	Name   string
	Health int
	Score  int
}

func (p *Player) TakeDamage(d int) {
	p.Health -= d
	if p.Health < 0 {
		p.Health = 0
	}
}

func (p *Player) Heal(h int) {
	p.Health += h
	if p.Health > 100 {
		p.Health = 100
	}
}

func (p Player) IsAlive() bool { return p.Health > 0 }

func main() {
	// Value semantics: must reassign
	inv1 := Inventory{}
	inv1 = addItemByValue(inv1, "Sword", 1)
	inv1 = addItemByValue(inv1, "Shield", 1)
	fmt.Printf("Inventory size (value): %d\n", inv1.Size)

	// Pointer semantics: direct modification
	inv2 := Inventory{}
	addItemByPointer(&inv2, "Bow", 1)
	addItemByPointer(&inv2, "Arrow", 50)
	fmt.Printf("Inventory size (pointer): %d\n", inv2.Size)

	// Game player demo
	player := Player{Name: "Warrior", Health: 100, Score: 0}
	fmt.Printf("%s: HP=%d\n", player.Name, player.Health)

	player.TakeDamage(40)
	fmt.Printf("After damage: HP=%d\n", player.Health)

	player.Heal(20)
	fmt.Printf("After heal: HP=%d\n", player.Health)

	player.TakeDamage(200) // more than max HP
	fmt.Printf("After lethal damage: HP=%d, alive=%v\n",
		player.Health, player.IsAlive())
}
